import{_ as e,o as r,c as s,a0 as a}from"./chunks/framework.DScjKhBS.js";const u=JSON.parse('{"title":"Skills, fitness & trade-offs","description":"Three SPDD skills, scenario fitness ratings, ROI vs upfront investment — from the Fowler-hosted SPDD article.","frontmatter":{"title":"Skills, fitness & trade-offs","description":"Three SPDD skills, scenario fitness ratings, ROI vs upfront investment — from the Fowler-hosted SPDD article."},"headers":[],"relativePath":"reports/structured-prompt-driven/04-skills-fitness-and-trade-offs.md","filePath":"reports/structured-prompt-driven/04-skills-fitness-and-trade-offs.md"}'),n={name:"reports/structured-prompt-driven/04-skills-fitness-and-trade-offs.md"};function o(i,t,d,l,h,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="skills-fitness-trade-offs" tabindex="-1">Skills, fitness &amp; trade-offs <a class="header-anchor" href="#skills-fitness-trade-offs" aria-label="Permalink to &quot;Skills, fitness &amp; trade-offs&quot;">​</a></h1><p>Thoughtworks identifies <strong>three core skills</strong> for SPDD. Separately, the article rates <strong>where SPDD fits</strong> and spells out <strong>benefits vs upfront investment</strong>. Below is a condensed mirror of those sections; see the <a href="https://martinfowler.com/articles/structured-prompt-driven/" target="_blank" rel="noreferrer">full article</a> for narrative detail.</p><hr><h2 id="three-core-skills" tabindex="-1">Three core skills <a class="header-anchor" href="#three-core-skills" aria-label="Permalink to &quot;Three core skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Essence</th></tr></thead><tbody><tr><td><strong>Abstraction first</strong></td><td><strong>Design before generate</strong> — objects, collaboration, boundaries. Without this, the model optimises locally while structure decays.</td></tr><tr><td><strong>Alignment</strong></td><td><strong>Lock intent</strong> — what we will/won’t do, standards, hard constraints <strong>before</strong> implementation. Otherwise: fast output, slow rework.</td></tr><tr><td><strong>Iterative review</strong></td><td><strong>Controlled loop</strong> — review and iterate so assistance behaves like engineering, not one-shot drafts (avoids endless patching or expensive restarts).</td></tr></tbody></table><hr><h2 id="fitness-assessment-star-ratings-from-the-article" tabindex="-1">Fitness assessment (star ratings from the article) <a class="header-anchor" href="#fitness-assessment-star-ratings-from-the-article" aria-label="Permalink to &quot;Fitness assessment (star ratings from the article)&quot;">​</a></h2><p>Higher stars = stronger fit for SPDD.</p><table tabindex="0"><thead><tr><th>Rating</th><th>Scenario</th><th>Notes</th></tr></thead><tbody><tr><td>★★★★★</td><td>Scaled, standardised delivery</td><td>Repeat business logic, long-term maintainability</td></tr><tr><td>★★★★★</td><td>High compliance / hard constraints</td><td>Regulated, security-heavy, strict architecture</td></tr><tr><td>★★★★☆</td><td>Collaboration / auditability</td><td>Traceable, reviewable end-to-end</td></tr><tr><td>★★★★☆</td><td>Cross-cutting consistency</td><td>Refactors across services or languages</td></tr><tr><td>★★☆☆☆</td><td>Firefighting hotfixes</td><td>Speed over discipline</td></tr><tr><td>★★☆☆☆</td><td>Exploratory spikes</td><td>Learning vs production quality</td></tr><tr><td>★★☆☆☆</td><td>One-off scripts</td><td>Disposable work</td></tr><tr><td>★☆☆☆☆</td><td>Context black holes</td><td>Domain/rules unclear</td></tr><tr><td>★☆☆☆☆</td><td>Pure creative / visual work</td><td>Taste-led rather than logic-led</td></tr></tbody></table><hr><h2 id="return-on-investment-summary-table" tabindex="-1">Return on investment (summary table) <a class="header-anchor" href="#return-on-investment-summary-table" aria-label="Permalink to &quot;Return on investment (summary table)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benefit</th><th>Impact</th><th>Horizon</th></tr></thead><tbody><tr><td>Determinism</td><td>High</td><td>Immediate</td></tr><tr><td>Traceability</td><td>High</td><td>Immediate</td></tr><tr><td>Faster reviews</td><td>High</td><td>Short-term</td></tr><tr><td>Explainability</td><td>Medium–high</td><td>Gradual</td></tr><tr><td>Safer evolution</td><td>High</td><td>Long-term</td></tr></tbody></table><hr><h2 id="upfront-investment-summary" tabindex="-1">Upfront investment (summary) <a class="header-anchor" href="#upfront-investment-summary" aria-label="Permalink to &quot;Upfront investment (summary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Nature</th></tr></thead><tbody><tr><td><strong>Mindset shift</strong></td><td>“Design first” vs “code first” — ongoing</td></tr><tr><td><strong>Senior expertise</strong></td><td>Translating business rules into clean abstractions — per feature</td></tr><tr><td><strong>Automation tooling</strong></td><td>Without tooling, throughput and consistency plateau; <strong>open-spdd</strong> is the article’s reference CLI</td></tr></tbody></table><p>The article notes SPDD can look <strong>“expert-only”</strong> today; longer-term direction is more <strong>organisation-level reuse</strong> of assets and machine-readable rules so the barrier lowers.</p><hr><h2 id="closing-angle" tabindex="-1">Closing angle <a class="header-anchor" href="#closing-angle" aria-label="Permalink to &quot;Closing angle&quot;">​</a></h2><p>SPDD is framed as strong in <strong>logic-heavy</strong> domains; <strong>aesthetic</strong> front-end work is called out as an area where stable patterns are still emerging.</p><p>Closing quote in the article (<strong>Richard Hamming</strong>):</p><blockquote><p>In science, if you know what you are doing, you shouldn’t be doing it. In engineering, if you don’t know what you are doing, you shouldn’t be doing it.</p></blockquote><hr><p><strong>Previous:</strong> <a href="./reports/structured-prompt-driven/03-case-study-billing-engine.html">Case study</a> · <strong>Next:</strong> <a href="./reports/structured-prompt-driven/05-sources-and-next-steps.html">Sources &amp; next steps</a></p>',23)])])}const f=e(n,[["render",o]]);export{u as __pageData,f as default};
